def need(ok,message):
    if not ok:raise ValueError(message)


def canonical(value):return(json.dumps(value,sort_keys=True,separators=(',',':'))+'\n').encode()
def sha(raw):return hashlib.sha256(raw).hexdigest()


def target(package,name):
    relative=PurePosixPath(name)
    need(type(name)is str and name and not relative.is_absolute()and '..'not in relative.parts
         and '\\'not in name and str(relative)==name,'Unsafe current-release path')
    path=Path(package)/name
    need(not any(p.is_symlink()for p in(path,*path.parents)if p.is_relative_to(package)),
         'Linked current-release input')
    return path


def identity(path):
    path=Path(path);need(path.is_file()and not path.is_symlink(),'Missing/linked current-release input: '+str(path))
    with path.open('rb')as stream:value=hashlib.file_digest(stream,'sha256').hexdigest()
    return dict(bytes=path.stat().st_size,sha256=value)


def read(package,name,pin=None):
    path=target(package,name);actual=identity(path)
    if pin is not None:
        need(actual['sha256']==(pin if isinstance(pin,str)else pin['sha256']),'Changed current-release record: '+name)
        if isinstance(pin,dict)and'bytes'in pin:need(actual['bytes']==pin['bytes'],'Changed record size')
    return json.loads(path.read_bytes())


def module(path,name):
    spec=importlib.util.spec_from_file_location(name,path);value=importlib.util.module_from_spec(spec)
    sys.modules[name]=value;spec.loader.exec_module(value);return value


def is_current(package):
    package=Path(package).resolve();path=package/'CANDIDATE.json'
    if not path.exists():return False
    record=read(package,'CANDIDATE.json')
    need(record['schema']=='long-context-private-recipient-v1'and record['image_sha256']!=OLD_IMAGE,
         'Invalid current-image construction record; historical evidence must stay historical')
    return True


def archive_files(archive,manifest_sha256):
    """Validate exact manifest-member bytes before extracting any source."""
    with zipfile.ZipFile(archive)as source:
        names=source.namelist();need(len(names)==len(set(names)),'Duplicate historical ZIP member')
        manifest_raw=source.read('MANIFEST.json');need(len(manifest_raw)<=8*1024*1024 and sha(manifest_raw)==manifest_sha256,
            'Historical manifest changed')
        manifest=json.loads(manifest_raw);need(set(names)==set(manifest['files'])|{'MANIFEST.json'},'Historical archive census differs')
        need(manifest['files']['prebuilt/seeded-sampling/project/impl/pnr/shared_product.fs']['sha256']==OLD_IMAGE,
             'Historical0e6 payload missing')
        need(sum(row['bytes']for row in manifest['files'].values())<=2*1024**3,'Unbounded historical archive')
        result={}
        for name in names:
            relative=PurePosixPath(name);info=source.getinfo(name);mode=(info.external_attr>>16)&0xffff
            need(name and str(relative)==name and not relative.is_absolute()and '..'not in relative.parts
                 and '\\'not in name and not info.is_dir()and(not mode or stat.S_ISREG(mode)),
                 'Unsafe/nonregular historical member')
            want=manifest['files'].get(name,dict(bytes=len(manifest_raw),sha256=manifest_sha256))
            need(0<=want['bytes']<=128*1024*1024 and info.file_size==want['bytes'],'Historical member size differs')
            raw=source.read(name);need(dict(bytes=len(raw),sha256=sha(raw))==want,'Historical member changed: '+name)
            result[name]=raw
        return result


def legacy_root(package):
    """Return original context for old APIs/fixtures; never mutate the package."""
    package=Path(package).resolve()
    if not is_current(package):return package
    record=read(package,'CANDIDATE.json');row=record['historical_release']
    need(row['manifest_sha256']==HISTORICAL_MANIFEST_SHA,'Historical context is not the reviewed exact0e6 release')
    archive=target(package,row['path'])
    need(identity(archive)=={key:row[key]for key in('bytes','sha256')},'Historical archive changed')
    key=(str(package),row['sha256'])
    if key not in _HISTORY_CACHE:
        contents=archive_files(archive,row['manifest_sha256'])
        folder=tempfile.TemporaryDirectory(prefix='checked-historical0e6-')
        destination=Path(folder.name)
        for name,raw in contents.items():
            path=destination/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw)
        _HISTORY_CACHE[key]=(folder,destination)
    return _HISTORY_CACHE[key][1]


def check_unchanged_greedy_payloads(package):
    """Old host evidence is read in history; active greedy FS/model bytes match."""
    historic=legacy_root(package);manifest=read(historic,'MANIFEST.json')
    names=['prebuilt/inference/project/impl/pnr/shared_product.fs',
        'prebuilt/kv-protected/project/impl/pnr/shared_product.fs',
        'prebuilt/encrypted-memory/project/impl/pnr/shared_product.fs',
        'assets/board1-real-semantic-image2048.bin','assets/board1-encrypted-model2048.bin']
    for name in names:need(identity(target(package,name))==manifest['files'][name],
        'An active greedy payload differs from its historical evidence: '+name)
    return True


